       `admin_id` bigint UNSIGNED NOT NULL COMMENT '管理员 id',                                        `action` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作标识，如 profile.update',                                        `summary` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '简述',                                        `ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户端 IP',                                        `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',                                        PRIMARY KEY (`id`) USING BTREE,                                        INDEX `idx_admin_time`(`admin_id` ASC, `create_time` ASC) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 341 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管理员操作日志' ROW_FORMAT = Dynamic;-- ------------------------------ Table structure for admin_role-- ----------------------------DROP TABLE IF EXISTS `admin_role`;CREATE TABLE `admin_role`  (                               `admin_id` bigint UNSIGNED NOT NULL,                               `role_id` bigint UNSIGNED NOT NULL,                               `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '{1:启用,0:停用}',                               PRIMARY KEY (`admin_id`, `role_id`) USING BTREE,                               INDEX `idx_role`(`role_id` ASC) USING BTREE) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;-- ------------------------------ Records of admin_role-- ----------------------------INSERT INTO `admin_role` VALUES (1, 1, 1);INSERT INTO `admin_role` VALUES (1, 10, 1);INSERT INTO `admin_role` VALUES (1, 11, 1);INSERT INTO `admin_role` VALUES (3, 10, 1);INSERT INTO `admin_role` VALUES (3, 11, 1);-- ------------------------------ Table structure for auth_role-- ----------------------------DROP TABLE IF EXISTS `auth_role`;CREATE TABLE `auth_role`  (                              `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',                              `pid` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '父级 id，0 为根（仅展示，无权限继承）',                              `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色名',                              `desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',                              `sort` int NOT NULL DEFAULT 0 COMMENT '排序',                              `status` tinyint NOT NULL DEFAULT 1 COMMENT '{1:启用,0:禁用}',                              `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',                              `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',                              PRIMARY KEY (`id`) USING BTREE,                              INDEX `idx_pid`(`pid` ASC) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权限角色' ROW_FORMAT = Dynamic;-- ------------------------------ Records of auth_role-- ----------------------------INSERT INTO `auth_role` VALUES (1, 0, '超级管理员', '拥有全部菜单（id=1 特例：未勾选也视为全量）', 0, 1, NULL, NULL);INSERT INTO `auth_role` VALUES (10, 0, '领导权限', '领导权限-只能查看、不能编辑', 0, 1, '2026-05-13 15:20:53', '2026-05-14 16:47:19');INSERT INTO `auth_role` VALUES (11, 1, '系统权限', '拥有所有权限，但需要进行鉴权逻辑', 0, 1, '2026-05-14 16:47:45', '2026-05-15 15:17:35');-- ------------------------------ Table structure for auth_role_rule-- ----------------------------DROP TABLE IF EXISTS `auth_role_rule`;CREATE TABLE `auth_role_rule`  (                                   `role_id` bigint UNSIGNED NOT NULL COMMENT '角色 id',                                   `rule_id` bigint UNSIGNED NOT NULL COMMENT 'auth_rule.id，且 scope=frontend',                                   PRIMARY KEY (`role_id`, `rule_id`) USING BTREE,                                   INDEX `idx_rule`(`rule_