icode_ci NOT NULL COMMENT '名称',                              `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '后端 api 路径或前端 path 片段',                              `method` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'HTTP 方法，api 用，如 GET POST *',                              `component` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '前端组件路径，view 用',                              `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '图标：{ep:ElementPlus图标组件名,url:图片绝对或相对地址}',                              `sort` int NOT NULL DEFAULT 0 COMMENT '排序',                              `status` tinyint NOT NULL DEFAULT 1 COMMENT '{1:启用,0:禁用}',                              `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',                              `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',                              PRIMARY KEY (`id`) USING BTREE,                              INDEX `idx_scope_pid`(`scope` ASC, `pid` ASC) USING BTREE,                              INDEX `idx_scope_status`(`scope` ASC, `status` ASC) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 683 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '权限规则（后端/前端双域树）' ROW_FORMAT = Dynamic;-- ------------------------------ Records of auth_rule-- ----------------------------INSERT INTO `auth_rule` VALUES (1, 'backend', 'menu', 0, '后端接口权限', NULL, NULL, NULL, NULL, 0, 1, NULL, NULL);INSERT INTO `auth_rule` VALUES (2, 'backend', 'api', 16, '规则树', 'auth.Rule/tree', 'GET', NULL, NULL, 0, 1, NULL, NULL);INSERT INTO `auth_rule` VALUES (3, 'backend', 'api', 16, '规则详情', 'auth.Rule/read', 'GET', NULL, NULL, 1, 1, NULL, NULL);INSERT INTO `auth_rule` VALUES (4, 'backend', 'api', 16, '新增规则', 'auth.Rule/save', 'POST', NULL, NULL, 2, 1, NULL, NULL);INSERT INTO `auth_rule` VALUES (5, 'backend', 'api', 16, '更新规则',