igint NULL DEFAULT NULL COMMENT '更新时间',                            PRIMARY KEY (`id`) USING BTREE,                            UNIQUE INDEX `uk_serial`(`serial` ASC) USING BTREE,                            INDEX `idx_expire_time`(`expire_time` ASC) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '登录RSA密钥' ROW_FORMAT = Dynamic;-- ------------------------------ Table structure for test_a_b_E-- ----------------------------DROP TABLE IF EXISTS `test_a_b_E`;CREATE TABLE `test_a_b_E`  (                               `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',                               `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '名字',                               PRIMARY KEY (`id`) USING BTREE) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'E' ROW_FORMAT = DYNAMIC;-- ------------------------------ Records of test_a_b_E-- ------------------------------ ------------------------------ Table structure for test_a_b_c-- ----------------------------DROP TABLE IF EXISTS `test_a_b_c`;CREATE TABLE `test_a_b_c`  (                               `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',                               `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '字段2',                               PRIMARY KEY (`id`) USING BTREE) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'C' ROW_FORMAT = DYNAMIC;-- ------------------------------ Records of test_a_b_c-- ----------------------------INSERT INTO `test_a_b_c` VALUES (1, 'aaa');-- ------------------------------ Table structure for test_a_b_d-- ----------------------------DROP TABLE IF EXISTS `test_a_b_d`;CREATE TABLE `test_a_b_d`  (                               `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',           